{"command":"python3 - <<'EOF'
# Mirror of `free -h`: free and available RAM, in GiB
meminfo = {}
with open("/proc/meminfo") as f:          # values are in kB
    for line in f:
        key, val, _ = line.split(None, 2)
        meminfo[key.rstrip(":")] = int(val)

def gib(kb):
    return f"{round(kb / 1024 / 1024)}Gi"  # same whole-GiB style as `free -h`

print("free:     ", gib(meminfo["MemFree"]))
print("available:", gib(meminfo["MemAvailable"]))
EOF"}

{"command":"python3 - <<'EOF'
# Mirror of `free -h`: free and available RAM, in GiB
meminfo = {}
with open("/proc/meminfo") as f:          # values are in kB
    for line in f:
        parts = line.split()
        meminfo[parts[0].rstrip(":")] = int(parts[1])

def gib(kb):
    return f"{round(kb / 1024 / 1024)}Gi"  # same whole-GiB style as `free -h`

print("free:     ", gib(meminfo["MemFree"]))
print("available:", gib(meminfo["MemAvailable"]))
EOF"}
